/* ========== 樱泉密事 · 界面美化 ========== */
/* —— 主题变量参考 ——
主色 #ff7a9c | 樱紫 #c8a2c8 | 樱花粉 #ffb7c5
深文字 #4a2c3d | 辅文字 #8a6478 | 米白 #fff5f7
*/

/* ===== 全局字体 ===== */
body, .markdown-body, #ai-chat-input, textarea, input {
  font-family: "Noto Serif JP", "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif !important;
}

/* ========== 一、消息气泡 ========== */
/* 气泡通用容器：毛玻璃+柔光 */
.group .bg-gray-100\/90 {
  background: linear-gradient(135deg, rgba(255,240,245,0.95), rgba(255,232,238,0.92)) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border: 1px solid rgba(255,154,178,0.28) !important;
  box-shadow: 0 6px 20px rgba(255,122,156,0.12), 0 0 16px rgba(255,183,197,0.18) !important;
  isolation: isolate !important;
  position: relative !important;
}

/* AI气泡区分色（更偏紫粉，营造梦境感） */
.chat-answer-container .bg-gray-100\/90 {
  background: linear-gradient(135deg, rgba(254,245,250,0.95), rgba(245,230,245,0.92)) !important;
  border: 1px solid rgba(200,162,200,0.3) !important;
  box-shadow: 0 6px 20px rgba(200,162,200,0.15), 0 0 18px rgba(255,183,197,0.2) !important;
}

/* 气泡圆角 */
.group .rounded-xl,
.chat-answer-container .rounded-xl {
  border-radius: 18px !important;
}

/* 气泡内边距 */
.group .px-4 { padding-left: 18px !important; padding-right: 18px !important; }
.group .py-3 { padding-top: 14px !important; padding-bottom: 14px !important; }

/* 文字颜色（高对比度） */
.group .text-gray-900,
.group .markdown-body,
.chat-answer-container .markdown-body {
  color: #4a2c3d !important;
  position: relative !important;
  z-index: 1 !important;
  background: transparent !important;
}

.group .text-sm {
  font-size: 15px !important;
  line-height: 1.85 !important;
  letter-spacing: 0.3px !important;
}

/* Markdown内强调元素 */
.group .markdown-body strong,
.chat-answer-container .markdown-body strong {
  color: #c44569 !important;
  font-weight: 700 !important;
}

.group .markdown-body em,
.chat-answer-container .markdown-body em {
  color: #8a4d6a !important;
  font-style: italic !important;
}

.group .markdown-body code,
.chat-answer-container .markdown-body code {
  background: rgba(255,183,197,0.22) !important;
  color: #9b2d4a !important;
  padding: 2px 7px !important;
  border-radius: 5px !important;
  font-size: 0.92em !important;
}

.group .markdown-body blockquote,
.chat-answer-container .markdown-body blockquote {
  border-left: 3px solid #ff7a9c !important;
  background: rgba(255,183,197,0.1) !important;
  padding: 8px 14px !important;
  border-radius: 0 8px 8px 0 !important;
  color: #6b3d52 !important;
}

/* 顶部装饰条美化 */
.group .bg-\[\#c9e1e9\] {
  background: linear-gradient(90deg, #ff7a9c, #ffb7c5, #c8a2c8) !important;
  height: 3px !important;
  border-radius: 2px !important;
  box-shadow: 0 0 8px rgba(255,122,156,0.4) !important;
}

.chat-answer-container .bg-\[\#F1CBCB\] {
  background: linear-gradient(90deg, #c8a2c8, #ffb7c5, #ff7a9c) !important;
  height: 3px !important;
  border-radius: 2px !important;
  box-shadow: 0 0 8px rgba(200,162,200,0.4) !important;
}

/* 模型标识 */
.chat-answer-container .text-purple-500.mt-1 {
  color: #c8a2c8 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
}

.chat-answer-container .text-orange-500 {
  color: #e85a7a !important;
  font-weight: 600 !important;
}

/* ========== 二、气泡内操作按钮 ========== */
.group .MuiButton-textPrimary {
  color: #c8769b !important;
  border-radius: 50% !important;
  transition: all 0.25s ease !important;
  min-width: 32px !important;
  width: 32px !important;
  height: 32px !important;
  padding: 6px !important;
}

.group .MuiButton-textPrimary:hover {
  background: rgba(255,122,156,0.15) !important;
  color: #ff5582 !important;
  transform: translateY(-2px) scale(1.08) !important;
  box-shadow: 0 4px 12px rgba(255,122,156,0.3) !important;
}

.group .MuiButton-textPrimary:active {
  transform: translateY(0) scale(0.95) !important;
}

.group .MuiButton-textPrimary svg {
  filter: drop-shadow(0 1px 2px rgba(255,122,156,0.25)) !important;
}

/* ========== 三、加载动画（SVG SMIL替换） ========== */
.style_dot-flashing__8L91Q {
  display: none !important;
}

.flex.items-center.justify-center.w-6.h-5 {
  position: relative !important;
  width: 60px !important;
  height: 24px !important;
}

.flex.items-center.justify-center.w-6.h-5::before {
  content: '' !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 60 24'><g><circle cx='12' cy='12' r='4' fill='%23ff7a9c'><animate attributeName='r' values='4;6;4' dur='1.2s' repeatCount='indefinite' begin='0s'/><animate attributeName='opacity' values='0.4;1;0.4' dur='1.2s' repeatCount='indefinite' begin='0s'/></circle><circle cx='30' cy='12' r='4' fill='%23ffb7c5'><animate attributeName='r' values='4;6;4' dur='1.2s' repeatCount='indefinite' begin='0.3s'/><animate attributeName='opacity' values='0.4;1;0.4' dur='1.2s' repeatCount='indefinite' begin='0.3s'/></circle><circle cx='48' cy='12' r='4' fill='%23c8a2c8'><animate attributeName='r' values='4;6;4' dur='1.2s' repeatCount='indefinite' begin='0.6s'/><animate attributeName='opacity' values='0.4;1;0.4' dur='1.2s' repeatCount='indefinite' begin='0.6s'/></circle></g></svg>") !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  filter: drop-shadow(0 0 4px rgba(255,183,197,0.6)) !important;
}

.style_text__zGhNq {
  color: #c8769b !important;
  font-size: 13px !important;
  letter-spacing: 1px !important;
}

/* ========== 四、顶部控制栏 ========== */
.sticky.top-0 {
  background: linear-gradient(180deg, rgba(255,245,247,0.95), rgba(255,232,238,0.85)) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-bottom: 1px solid rgba(255,154,178,0.2) !important;
  box-shadow: 0 2px 12px rgba(255,122,156,0.08) !important;
}

/* 模型选择器 */
#ai-model-selector {
  background: linear-gradient(135deg, rgba(255,255,255,0.7), rgba(255,240,245,0.6)) !important;
  border: 1px solid rgba(255,154,178,0.35) !important;
  border-radius: 14px !important;
  color: #4a2c3d !important;
  transition: all 0.25s ease !important;
  box-shadow: 0 2px 8px rgba(255,122,156,0.1) !important;
}

#ai-model-selector:hover {
  background: linear-gradient(135deg, rgba(255,255,255,0.95), rgba(255,232,238,0.85)) !important;
  border-color: #ff7a9c !important;
  box-shadow: 0 4px 14px rgba(255,122,156,0.22) !important;
}

#ai-model-selector .truncate {
  color: #4a2c3d !important;
  font-weight: 600 !important;
  font-size: 14px !important;
}

#ai-model-selector svg[data-icon="ChevronDown"] {
  color: #ff7a9c !important;
}

/* 设置按钮 */
#header-setting-button {
  color: #c8769b !important;
  border-radius: 50% !important;
  transition: all 0.3s ease !important;
}

#header-setting-button:hover {
  color: #ff5582 !important;
  background: rgba(255,122,156,0.12) !important;
  transform: rotate(60deg) !important;
}

/* 移动端历史/音乐按钮 */
.lucide-clock8.md\:hidden,
button .lucide-music2 {
  color: #c8769b !important;
  transition: all 0.25s ease !important;
}

button .lucide-music2:hover,
.lucide-clock8.md\:hidden:hover {
  color: #ff5582 !important;
  filter: drop-shadow(0 0 6px rgba(255,122,156,0.5)) !important;
}

/* ========== 五、快捷按钮组 ========== */
#ai-mod-button2 .MuiButton-outlinedPrimary {
  background: linear-gradient(135deg, rgba(255,255,255,0.85), rgba(255,240,245,0.75)) !important;
  border: 1px solid rgba(255,154,178,0.4) !important;
  color: #c8769b !important;
  border-radius: 16px !important;
  font-weight: 600 !important;
  transition: all 0.25s ease !important;
  box-shadow: 0 2px 6px rgba(255,122,156,0.1) !important;
}

#ai-mod-button2 .MuiButton-outlinedPrimary:hover {
  background: linear-gradient(135deg, #ff7a9c, #c8a2c8) !important;
  color: #ffffff !important;
  border-color: transparent !important;
  transform: translateY(-2px) !important;
  box-shadow: 0 6px 16px rgba(255,122,156,0.4), 0 0 20px rgba(255,183,197,0.4) !important;
}

#ai-mod-button2 .MuiButton-outlinedPrimary:hover svg {
  color: #ffffff !important;
}

#ai-mod-button2 svg {
  color: #c8769b !important;
}

/* ========== 六、底部输入区 ========== */
.bg-gradient-to-t {
  background: linear-gradient(180deg, transparent, rgba(255,245,247,0.85), rgba(255,232,238,0.95)) !important;
}

.bg-white.border-\[1\.5px\] {
  background: linear-gradient(135deg, rgba(255,255,255,0.92), rgba(255,248,250,0.88)) !important;
  border: 1.5px solid rgba(255,154,178,0.4) !important;
  border-radius: 22px !important;
  box-shadow: 0 4px 20px rgba(255,122,156,0.12), 0 0 24px rgba(255,183,197,0.15) !important;
  transition: all 0.3s ease !important;
}

.bg-white.border-\[1\.5px\]:focus-within {
  border-color: #ff7a9c !important;
  box-shadow: 0 0 0 3px rgba(255,122,156,0.15), 0 6px 24px rgba(255,122,156,0.22), 0 0 32px rgba(255,183,197,0.3) !important;
}

#ai-chat-input {
  color: #4a2c3d !important;
  font-size: 15px !important;
  line-height: 1.7 !important;
  background: transparent !important;
}

#ai-chat-input::placeholder {
  color: #c9a8b5 !important;
  font-style: italic !important;
}

#ai-chat-input::selection {
  background: rgba(255,122,156,0.3) !important;
  color: #4a2c3d !important;
}

/* 字符计数器 */
.absolute.bottom-2.right-2 .bg-gray-100 {
  background: rgba(255,183,197,0.2) !important;
  color: #8a6478 !important;
  border-radius: 10px !important;
  font-size: 11px !important;
  padding: 2px 8px !important;
  border: 1px solid rgba(255,154,178,0.25) !important;
}

/* 发送按钮 */
#ai-send-button {
  background: linear-gradient(135deg, #ff7a9c, #c8a2c8) !important;
  border-radius: 50% !important;
  transition: all 0.3s ease !important;
  box-shadow: 0 4px 14px rgba(255,122,156,0.4), 0 0 20px rgba(255,183,197,0.35) !important;
}

#ai-send-button:hover {
  transform: scale(1.1) rotate(-8deg) !important;
  box-shadow: 0 6px 20px rgba(255,122,156,0.55), 0 0 28px rgba(255,183,197,0.5) !important;
}

#ai-send-button:active {
  transform: scale(0.95) !important;
}

#ai-send-button .icon-icon-send {
  color: #ffffff !important;
  filter: drop-shadow(0 1px 2px rgba(0,0,0,0.15)) !important;
}

/* ========== 七、分页控制 ========== */
.MuiPaginationItem-root {
  color: #8a6478 !important;
  border-radius: 10px !important;
  font-weight: 600 !important;
  transition: all 0.2s ease !important;
}

.MuiPaginationItem-root:hover {
  background: rgba(255,183,197,0.2) !important;
  color: #ff5582 !important;
}

.MuiPaginationItem-root.Mui-selected {
  background: linear-gradient(135deg, #ff7a9c, #c8a2c8) !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(255,122,156,0.35) !important;
}

.MuiPaginationItem-root.Mui-disabled {
  color: #d4b8c5 !important;
  opacity: 0.5 !important;
}

.MuiPaginationItem-previousNext .MuiPaginationItem-icon {
  color: #c8769b !important;
}

.forum-pagination-input-wrapper .MuiInputBase-input {
  background: rgba(255,255,255,0.7) !important;
  border: 1px solid rgba(255,154,178,0.35) !important;
  border-radius: 8px !important;
  color: #4a2c3d !important;
}

.MuiStack-root.text-sm .MuiBox-root {
  color: #8a6478 !important;
}

/* ========== 八、评论区 ========== */
/* 面板主容器（仅视觉，不动定位） */
.absolute.inset-x-0.bottom-0.z-20.bg-white {
  background: linear-gradient(180deg, rgba(255,245,247,0.98), rgba(255,232,238,0.96)) !important;
  backdrop-filter: blur(16px) !important;
  -webkit-backdrop-filter: blur(16px) !important;
  border-top: 1px solid rgba(255,154,178,0.3) !important;
  border-radius: 24px 24px 0 0 !important;
  box-shadow: 0 -8px 32px rgba(255,122,156,0.18) !important;
}

.text-lg.font-bold.pl-3 {
  color: #4a2c3d !important;
  background: linear-gradient(135deg, #ff7a9c, #c8a2c8) !important;
  -webkit-background-clip: text !important;
  background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  font-weight: 700 !important;
  letter-spacing: 1px !important;
}

button[aria-label="close"] {
  color: #c8769b !important;
  transition: all 0.25s ease !important;
  border-radius: 50% !important;
}

button[aria-label="close"]:hover {
  color: #ff5582 !important;
  background: rgba(255,122,156,0.12) !important;
  transform: rotate(90deg) !important;
}

/* 评分区域 */
.MuiStack-root.px-3 p.text-grey-600 {
  color: #6b3d52 !important;
  font-weight: 600 !important;
}

.MuiRating-iconEmpty {
  color: rgba(255,154,178,0.35) !important;
}

.MuiRating-iconFilled {
  color: #ff7a9c !important;
  filter: drop-shadow(0 0 4px rgba(255,122,156,0.5)) !important;
}

.text-orange-500.w-14 {
  color: #e85a7a !important;
  font-weight: 700 !important;
}

/* 评论输入框 */
.flex.flex-col.border-\[1\.5px\].border-gray-200 {
  background: rgba(255,255,255,0.85) !important;
  border: 1.5px solid rgba(255,154,178,0.35) !important;
  border-radius: 16px !important;
  transition: all 0.25s ease !important;
}

.flex.flex-col.border-\[1\.5px\].border-gray-200:focus-within {
  border-color: #ff7a9c !important;
  box-shadow: 0 0 0 3px rgba(255,122,156,0.15), 0 4px 16px rgba(255,122,156,0.18) !important;
}

textarea[placeholder="发表评论"] {
  color: #4a2c3d !important;
  font-size: 14px !important;
  line-height: 1.7 !important;
  background: transparent !important;
}

textarea[placeholder="发表评论"]::placeholder {
  color: #c9a8b5 !important;
  font-style: italic !important;
}

.bg-gray-100.text-xs.font-medium {
  background: rgba(255,183,197,0.2) !important;
  color: #8a6478 !important;
  border-radius: 8px !important;
  padding: 2px 7px !important;
}

#basic-button {
  color: #c8769b !important;
  transition: all 0.2s ease !important;
}

#basic-button:hover {
  color: #ff5582 !important;
  transform: scale(1.15) !important;
}

/* 评论发送按钮 */
div[data-state="closed"] .cursor-pointer.group {
  background: linear-gradient(135deg, #ff7a9c, #c8a2c8) !important;
  border-radius: 50% !important;
  padding: 8px !important;
  transition: all 0.3s ease !important;
  box-shadow: 0 3px 10px rgba(255,122,156,0.35) !important;
}

div[data-state="closed"] .cursor-pointer.group:hover {
  transform: scale(1.1) rotate(-8deg) !important;
  box-shadow: 0 5px 16px rgba(255,122,156,0.5) !important;
}

svg[data-icon="Send03"] {
  color: #ffffff !important;
}

/* 排序按钮 */
.MuiButton-containedPrimary {
  background: linear-gradient(135deg, #ff7a9c, #c8a2c8) !important;
  color: #ffffff !important;
  border-radius: 14px !important;
  font-weight: 600 !important;
  box-shadow: 0 3px 10px rgba(255,122,156,0.3) !important;
}

.MuiButton-outlinedPrimary {
  background: rgba(255,255,255,0.7) !important;
  color: #c8769b !important;
  border: 1px solid rgba(255,154,178,0.4) !important;
  border-radius: 14px !important;
  font-weight: 600 !important;
}

.MuiButton-outlinedPrimary:hover {
  background: rgba(255,183,197,0.18) !important;
  border-color: #ff7a9c !important;
}

/* 分割线 */
.style_divider__mW0YX {
  background: linear-gradient(90deg, transparent, rgba(255,154,178,0.4), transparent) !important;
  height: 1px !important;
}

/* 评论列表 */
.p-3.overflow-y-auto.h-full {
  scrollbar-width: thin !important;
  scrollbar-color: #ffb7c5 transparent !important;
}

.p-3.overflow-y-auto.h-full::-webkit-scrollbar {
  width: 6px !important;
}

.p-3.overflow-y-auto.h-full::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #ff7a9c, #c8a2c8) !important;
  border-radius: 3px !important;
}

.p-3.overflow-y-auto.h-full::-webkit-scrollbar-track {
  background: transparent !important;
}

/* 评论项 */
img.rounded-full {
  border: 2px solid rgba(255,154,178,0.4) !important;
  box-shadow: 0 2px 8px rgba(255,122,156,0.15) !important;
}

.text-sm.text-grey-600 span.font-bold {
  color: #c44569 !important;
  font-weight: 700 !important;
}

div.break-all {
  color: #4a2c3d !important;
  line-height: 1.75 !important;
}

.text-xs.text-grey-600 {
  color: #8a6478 !important;
}

button.text-gray-400 {
  color: #c8a2c8 !important;
  transition: all 0.2s ease !important;
}

button.text-gray-400:hover {
  color: #ff5582 !important;
  transform: scale(1.1) !important;
}

span.cursor-pointer {
  color: #c8769b !important;
  font-weight: 600 !important;
  transition: color 0.2s ease !important;
}

span.cursor-pointer:hover {
  color: #ff5582 !important;
}

div.ml-8.border-l {
  border-color: rgba(255,154,178,0.3) !important;
}

/* ========== 九、响应式与降级 ========== */
@media (max-width: 768px) {
  .group .text-sm { font-size: 14px !important; }
  .group .px-4 { padding-left: 14px !important; padding-right: 14px !important; }
  #ai-mod-button2 .MuiButton-outlinedPrimary { font-size: 12px !important; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ========== 樱泉密事 · 叙事状态面板美化 ========== */
.relink-scope{
  --rs-primary:#ff7a9c;--rs-accent:#c8a2c8;--rs-sakura:#ffb7c5;
  --rs-text:#4a2c3d;--rs-text-sub:#8a6478;--rs-text-light:#a88497;
  --rs-bg-card:rgba(255,250,252,0.96);--rs-bg-soft:rgba(255,240,245,0.85);
  --rs-bg-inner:rgba(255,255,255,0.7);
  --rs-border:rgba(255,154,178,0.32);--rs-border-soft:rgba(200,162,200,0.22);
  --rs-shadow:0 10px 36px rgba(255,122,156,0.18),0 0 24px rgba(255,183,197,0.15);
  --rs-glow:0 0 16px rgba(255,183,197,0.45);
  --rs-radius:18px;--rs-radius-sm:10px;
  --rs-lv1:#a8d8b9;--rs-lv2:#ffd97d;--rs-lv3:#ffa07a;--rs-lv4:#ff6b8a;--rs-lv5:#c44569;
  font-family:"Noto Serif JP","PingFang SC","Microsoft YaHei",serif;
  color:var(--rs-text);
  max-width:880px;margin:18px auto;padding:22px;
  background:linear-gradient(135deg,rgba(255,245,247,0.92),rgba(245,232,245,0.88)),
    radial-gradient(ellipse at top right,rgba(255,183,197,0.18),transparent 60%);
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
  border:1px solid var(--rs-border);border-radius:24px;
  box-shadow:var(--rs-shadow);
  position:relative;overflow:hidden;
  animation:rs-fade-in 0.8s ease both;
}
.relink-scope::before{content:"";position:absolute;top:0;left:0;right:0;height:3px;
  background:linear-gradient(90deg,var(--rs-primary),var(--rs-sakura),var(--rs-accent),var(--rs-primary));
  background-size:200% 100%;animation:rs-flow 4s linear infinite;}
@keyframes rs-fade-in{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
@keyframes rs-flow{0%{background-position:0% 0}100%{background-position:200% 0}}
@keyframes rs-stripes{0%{background-position:0 0}100%{background-position:32px 0}}
@keyframes rs-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
@keyframes rs-glow-pulse{0%,100%{box-shadow:0 0 12px rgba(255,122,156,0.3)}50%{box-shadow:0 0 22px rgba(255,122,156,0.55)}}
@keyframes rs-fill-grow{from{width:0!important}}

/* ========== 场景头部 ========== */
.relink-scope .rs-scene-header{margin-bottom:18px;padding:14px 16px;
  background:linear-gradient(135deg,rgba(255,255,255,0.7),rgba(255,240,245,0.6));
  border:1px solid var(--rs-border-soft);border-radius:var(--rs-radius);
  box-shadow:inset 0 1px 0 rgba(255,255,255,0.6);}
.relink-scope .rs-tags-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:10px;}
.relink-scope .rs-tag{display:flex;align-items:center;gap:6px;padding:8px 12px;
  background:linear-gradient(135deg,rgba(255,255,255,0.85),rgba(255,232,238,0.7));
  border:1px solid var(--rs-border);border-radius:12px;font-size:13px;color:var(--rs-text);
  box-shadow:0 2px 6px rgba(255,122,156,0.08);transition:transform 0.25s ease;}
.relink-scope .rs-tag:hover{transform:translateY(-2px);box-shadow:0 4px 12px rgba(255,122,156,0.2);}
.relink-scope .rs-tag b{color:var(--rs-primary);font-weight:700;}
.relink-scope .rs-icon{font-size:14px;filter:drop-shadow(0 0 4px rgba(255,183,197,0.6));}
.relink-scope .rs-scene-desc{padding:10px 14px;background:rgba(255,183,197,0.12);
  border-left:3px solid var(--rs-primary);border-radius:0 10px 10px 0;
  font-size:14px;color:var(--rs-text);}
.relink-scope .rs-scene-desc b{color:var(--rs-primary);font-weight:700;}

/* ========== 剧情正文 ========== */
.relink-scope .rs-story-content{padding:22px 24px;margin-bottom:20px;
  background:var(--rs-bg-card);border:1px solid var(--rs-border-soft);
  border-radius:var(--rs-radius);box-shadow:inset 0 0 24px rgba(255,183,197,0.08);
  font-size:15.5px;line-height:2;letter-spacing:0.4px;color:var(--rs-text);
  text-align:justify;position:relative;}
.relink-scope .rs-story-content::before{content:"❀";position:absolute;top:14px;right:18px;
  color:var(--rs-sakura);font-size:20px;opacity:0.5;animation:rs-float 3s ease infinite;}
.relink-scope .rs-story-content .story-image{margin:14px auto;display:block;border-radius:14px;
  box-shadow:0 8px 24px rgba(255,122,156,0.25);}

/* ========== 状态面板布局 ========== */
.relink-scope .rs-status-panel{display:grid;grid-template-columns:240px 1fr;gap:18px;margin-bottom:18px;}

/* ===== 左栏 ===== */
.relink-scope .rs-panel-left{padding:18px 14px;
  background:linear-gradient(160deg,rgba(255,250,252,0.95),rgba(255,232,238,0.85));
  border:1px solid var(--rs-border);border-radius:var(--rs-radius);
  box-shadow:var(--rs-shadow);text-align:center;}
.relink-scope .rs-avatar-box{position:relative;width:160px;height:240px;margin:0 auto 14px;
  border-radius:14px;overflow:hidden;
  box-shadow:0 12px 28px rgba(255,122,156,0.3),0 0 24px rgba(255,183,197,0.4);
  animation:rs-glow-pulse 3.5s ease infinite;}
.relink-scope .rs-avatar-box::after{content:"";position:absolute;inset:0;
  background:linear-gradient(180deg,transparent 65%,rgba(74,44,61,0.35));pointer-events:none;}
.relink-scope .rs-avatar{width:100%;height:100%;background-size:cover;background-position:center top;}
.relink-scope .rs-name{font-size:18px;font-weight:700;color:var(--rs-text);margin-bottom:6px;
  letter-spacing:1px;text-shadow:0 1px 2px rgba(255,255,255,0.6);}
.relink-scope .rs-age{font-size:13px;color:var(--rs-primary);font-weight:600;margin-left:4px;}
.relink-scope .rs-identity{display:inline-block;padding:4px 12px;margin-bottom:10px;
  background:linear-gradient(135deg,var(--rs-primary),var(--rs-accent));
  color:#fff;font-size:12px;border-radius:14px;font-weight:600;letter-spacing:0.5px;
  box-shadow:0 3px 10px rgba(255,122,156,0.35);}
.relink-scope .rs-mood,.relink-scope .rs-pose{font-size:12.5px;color:var(--rs-text-sub);
  padding:6px 10px;margin-top:8px;background:rgba(255,255,255,0.6);border-radius:10px;
  border:1px solid var(--rs-border-soft);text-align:left;line-height:1.6;}
.relink-scope .rs-mood span,.relink-scope .rs-pose span{color:var(--rs-text);font-weight:600;}

/* ===== 右栏 ===== */
.relink-scope .rs-panel-right{padding:18px;
  background:var(--rs-bg-card);border:1px solid var(--rs-border);
  border-radius:var(--rs-radius);box-shadow:var(--rs-shadow);}

/* 进度条组 */
.relink-scope .rs-bar-group{margin-bottom:16px;}
.relink-scope .rs-progress-container{margin-bottom:12px;}
.relink-scope .rs-progress-container:last-child{margin-bottom:0;}
.relink-scope .rs-progress-label{display:flex;justify-content:space-between;align-items:center;
  font-size:13px;margin-bottom:6px;}
.relink-scope .rs-label-title{color:var(--rs-text);font-weight:600;}
.relink-scope .rs-highlight{color:var(--rs-primary);font-weight:700;font-size:12px;
  padding:1px 8px;background:rgba(255,122,156,0.12);border-radius:8px;margin-left:4px;}
.relink-scope .rs-label-value{color:var(--rs-text-sub);font-weight:700;font-size:12.5px;
  font-variant-numeric:tabular-nums;}
.relink-scope .rs-progress-track{height:12px;border-radius:8px;
  background:rgba(255,183,197,0.18);overflow:hidden;
  box-shadow:inset 0 2px 4px rgba(196,69,105,0.12);position:relative;}
.relink-scope .rs-progress-fill{height:100%;border-radius:8px;position:relative;
  background-image:linear-gradient(135deg,var(--rs-primary),var(--rs-accent)),
    linear-gradient(45deg,rgba(255,255,255,0.18) 25%,transparent 25%,transparent 50%,
    rgba(255,255,255,0.18) 50%,rgba(255,255,255,0.18) 75%,transparent 75%);
  background-size:100% 100%,16px 16px;background-blend-mode:overlay;
  box-shadow:0 0 12px rgba(255,122,156,0.5);
  animation:rs-fill-grow 1.4s cubic-bezier(0.34,1.2,0.64,1) both,rs-stripes 1.2s linear infinite;}
.relink-scope .rs-fill-danger{background-image:linear-gradient(135deg,#c44569,#ff6b8a),
  linear-gradient(45deg,rgba(255,255,255,0.18) 25%,transparent 25%,transparent 50%,
  rgba(255,255,255,0.18) 50%,rgba(255,255,255,0.18) 75%,transparent 75%);
  box-shadow:0 0 14px rgba(196,69,105,0.55);}
.relink-scope .rs-fill-lust{background-image:linear-gradient(135deg,#ff5582,#ffb7c5),
  linear-gradient(45deg,rgba(255,255,255,0.18) 25%,transparent 25%,transparent 50%,
  rgba(255,255,255,0.18) 50%,rgba(255,255,255,0.18) 75%,transparent 75%);
  box-shadow:0 0 14px rgba(255,107,138,0.6);}
.relink-scope .rs-fill-preg{background-image:linear-gradient(135deg,#e85a7a,#c8a2c8),
  linear-gradient(45deg,rgba(255,255,255,0.18) 25%,transparent 25%,transparent 50%,
  rgba(255,255,255,0.18) 50%,rgba(255,255,255,0.18) 75%,transparent 75%);
  box-shadow:0 0 14px rgba(232,90,122,0.5);}

/* 开发度网格 */
.relink-scope .rs-dev-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-bottom:14px;}
.relink-scope .rs-dev-item{padding:10px 12px;
  background:linear-gradient(135deg,rgba(255,255,255,0.85),rgba(255,240,245,0.7));
  border:1px solid var(--rs-border-soft);border-radius:12px;
  transition:transform 0.25s ease,box-shadow 0.25s ease;}
.relink-scope .rs-dev-item:hover{transform:translateY(-2px);
  box-shadow:0 6px 16px rgba(255,122,156,0.18);border-color:var(--rs-primary);}
.relink-scope .rs-dev-title{font-size:13px;font-weight:700;color:var(--rs-primary);margin-bottom:4px;}
.relink-scope .rs-dev-value{font-size:11.5px;color:var(--rs-text-sub);font-weight:600;margin-bottom:4px;
  font-variant-numeric:tabular-nums;}
.relink-scope .rs-dev-desc{font-size:11.5px;color:var(--rs-text);line-height:1.55;
  padding-top:4px;border-top:1px dashed var(--rs-border-soft);}

/* 腔内情况 */
.relink-scope .rs-bq-box{margin-bottom:12px;padding:12px;
  background:linear-gradient(135deg,rgba(255,232,238,0.6),rgba(245,220,235,0.5));
  border:1px solid var(--rs-border);border-radius:12px;}
.relink-scope .rs-bq-title{font-size:13px;font-weight:700;color:var(--rs-primary);margin-bottom:8px;
  display:flex;align-items:center;gap:4px;}
.relink-scope .rs-bq-box .story-image{display:block;margin:8px auto;border-radius:10px;max-width:100%;
  box-shadow:0 4px 14px rgba(255,122,156,0.2);}
.relink-scope .rs-bq-desc{font-size:12.5px;color:var(--rs-text);line-height:1.7;margin-bottom:6px;}
.relink-scope .rs-bq-meta{font-size:12px;color:var(--rs-text-sub);padding-top:6px;
  border-top:1px dashed var(--rs-border-soft);}

/* 信息行 */
.relink-scope .rs-info-row{display:flex;gap:10px;padding:8px 0;
  border-bottom:1px dashed var(--rs-border-soft);font-size:13px;}
.relink-scope .rs-info-row:last-of-type{border-bottom:none;}
.relink-scope .rs-info-label{flex:0 0 90px;color:var(--rs-primary);font-weight:700;}
.relink-scope .rs-info-content{flex:1;color:var(--rs-text);line-height:1.7;}
.relink-scope .rs-info-content b{color:var(--rs-lv5);font-weight:700;}

/* 引用框 */
.relink-scope .rs-quote-box{margin-top:14px;padding:14px 16px 14px 40px;position:relative;
  background:linear-gradient(135deg,rgba(255,245,247,0.9),rgba(245,232,245,0.85));
  border:1px solid var(--rs-border);border-radius:12px;border-left:3px solid var(--rs-primary);
  box-shadow:0 4px 14px rgba(255,122,156,0.12);
  animation:rs-fade-in 1s ease 0.3s both;}
.relink-scope .rs-quote-icon{position:absolute;left:10px;top:6px;font-size:36px;line-height:1;
  color:var(--rs-primary);font-family:Georgia,serif;opacity:0.45;}
.relink-scope .rs-quote-text{font-size:13.5px;color:var(--rs-text);line-height:1.85;
  font-style:italic;letter-spacing:0.3px;}

/* ========== 剧情走向推荐（无动效） ========== */
.relink-scope .rs-choices-box{padding:18px;
  background:linear-gradient(135deg,rgba(255,250,252,0.95),rgba(255,240,245,0.88));
  border:1px solid var(--rs-border);border-radius:var(--rs-radius);
  box-shadow:var(--rs-shadow);}
.relink-scope .rs-choice-header{font-size:15px;font-weight:700;color:var(--rs-primary);
  margin-bottom:12px;padding-bottom:8px;border-bottom:2px solid var(--rs-border);
  letter-spacing:1px;}
.relink-scope .rs-choice-list{display:grid;gap:8px;}
.relink-scope .rs-choice-item{display:flex;align-items:flex-start;gap:12px;padding:10px 12px;
  background:rgba(255,255,255,0.7);border:1px solid var(--rs-border-soft);border-radius:10px;}
.relink-scope .rs-choice-key{flex:0 0 28px;height:28px;display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,var(--rs-primary),var(--rs-accent));color:#fff;
  font-weight:700;font-size:13px;border-radius:8px;
  box-shadow:0 2px 6px rgba(255,122,156,0.3);}
.relink-scope .rs-choice-text{flex:1;font-size:13.5px;color:var(--rs-text);line-height:1.7;
  padding-top:3px;}

/* ========== 响应式 ========== */
@media (max-width:768px){
  .relink-scope{padding:16px;margin:12px;}
  .relink-scope .rs-tags-grid{grid-template-columns:repeat(2,1fr);}
  .relink-scope .rs-status-panel{grid-template-columns:1fr;}
  .relink-scope .rs-panel-left{padding:14px;}
  .relink-scope .rs-avatar-box{width:140px;height:210px;}
  .relink-scope .rs-dev-grid{grid-template-columns:1fr;}
  .relink-scope .rs-story-content{padding:16px;font-size:14.5px;}
  .relink-scope .rs-info-label{flex:0 0 80px;}
}
@media (prefers-reduced-motion:reduce){
  .relink-scope,.relink-scope *,.relink-scope *::before,.relink-scope *::after{
    animation-duration:0.01ms!important;animation-iteration-count:1!important;
    transition-duration:0.01ms!important;}
  .relink-scope .rs-progress-fill{animation:none!important;}
}

/* ========== 补丁：立绘+第三框+移动端修复 ========== */

/* ① 状态面板改为：上(左右两栏) + 下(整行第三框) */
.relink-scope .rs-status-panel{
  display:grid!important;
  grid-template-columns:260px 1fr!important;
  grid-template-areas:"left right" "bottom bottom"!important;
  gap:18px!important;
}
.relink-scope .rs-panel-left{grid-area:left;}
.relink-scope .rs-panel-right{grid-area:right;}
.relink-scope .rs-panel-bottom{grid-area:bottom;}

/* ② 左栏立绘放大 + 四边等距 */
.relink-scope .rs-panel-left{
  padding:16px!important;
  display:flex!important;
  flex-direction:column!important;
  align-items:stretch!important;
}
.relink-scope .rs-avatar-box{
  width:100%!important;
  height:auto!important;
  aspect-ratio:2/3!important;
  max-width:none!important;
  margin:0 0 14px 0!important;
  border-radius:12px!important;
  overflow:hidden!important;
  position:relative!important;
  box-shadow:0 12px 28px rgba(255,122,156,0.3),0 0 24px rgba(255,183,197,0.4)!important;
}
.relink-scope .rs-avatar{
  position:absolute!important;
  inset:0!important;
  width:100%!important;
  height:100%!important;
  background-size:cover!important;
  background-position:center center!important;
  background-repeat:no-repeat!important;
}

/* ③ 第三框样式（防线/欲望/视角/引用） */
.relink-scope .rs-panel-bottom{
  padding:18px 20px!important;
  background:var(--rs-bg-card)!important;
  border:1px solid var(--rs-border)!important;
  border-radius:var(--rs-radius)!important;
  box-shadow:var(--rs-shadow)!important;
  position:relative!important;
}
.relink-scope .rs-panel-bottom::before{
  content:""!important;position:absolute!important;
  top:0!important;left:20px!important;right:20px!important;height:2px!important;
  background:linear-gradient(90deg,transparent,var(--rs-primary),var(--rs-accent),transparent)!important;
  border-radius:0 0 2px 2px!important;
}

/* 第三框内的info-row布局优化 */
.relink-scope .rs-panel-bottom .rs-info-row{
  padding:10px 0!important;
  font-size:13.5px!important;
}
.relink-scope .rs-panel-bottom .rs-info-label{flex:0 0 100px!important;}
.relink-scope .rs-panel-bottom .rs-quote-box{margin-top:14px!important;}

/* ========== 移动端补丁 ========== */
@media (max-width:768px){
  .relink-scope .rs-status-panel{
    grid-template-columns:1fr!important;
    grid-template-areas:"left" "right" "bottom"!important;
    gap:14px!important;
  }
  /* 修复立绘错位：使用aspect-ratio强制比例，居中显示 */
  .relink-scope .rs-panel-left{
    padding:14px!important;
    align-items:center!important;
  }
  .relink-scope .rs-avatar-box{
    width:78%!important;
    max-width:280px!important;
    aspect-ratio:2/3!important;
    height:auto!important;
    margin:0 auto 12px auto!important;
  }
  .relink-scope .rs-avatar{
    position:absolute!important;
    inset:0!important;
    width:100%!important;
    height:100%!important;
    background-position:center center!important;
    background-size:cover!important;
  }
  /* 名称等信息居中显示 */
  .relink-scope .rs-name,
  .relink-scope .rs-identity{text-align:center!important;}
  .relink-scope .rs-mood,
  .relink-scope .rs-pose{font-size:12px!important;}
  /* 第三框移动端 */
  .relink-scope .rs-panel-bottom{padding:14px!important;}
  .relink-scope .rs-panel-bottom .rs-info-row{
    flex-direction:column!important;
    gap:4px!important;
    padding:8px 0!important;
  }
  .relink-scope .rs-panel-bottom .rs-info-label{flex:none!important;font-size:12.5px!important;}
}

@media (max-width:480px){
  .relink-scope .rs-avatar-box{width:88%!important;}
}

/* ========== 补丁：立绘对齐 + 移除进度条流光 ========== */

/* ① 修复立绘下串：story-image可能携带外部margin/padding/display样式 */
.relink-scope .rs-avatar-box{
  display:block!important;
  font-size:0!important;
  line-height:0!important;
}
.relink-scope .rs-avatar-box .rs-avatar,
.relink-scope .rs-avatar-box .story-image{
  position:absolute!important;
  top:0!important;left:0!important;right:0!important;bottom:0!important;
  inset:0!important;
  width:100%!important;
  height:100%!important;
  margin:0!important;
  padding:0!important;
  display:block!important;
  background-size:cover!important;
  background-position:center center!important;
  background-repeat:no-repeat!important;
  border-radius:0!important;
  box-shadow:none!important;
  vertical-align:top!important;
}

/* ② 移除进度条条纹流光动画，保留填充增长动画 */
.relink-scope .rs-progress-fill,
.relink-scope .rs-fill-danger,
.relink-scope .rs-fill-lust,
.relink-scope .rs-fill-preg{
  background-image:none!important;
  animation:rs-fill-grow 1.4s cubic-bezier(0.34,1.2,0.64,1) both!important;
  background-size:auto!important;
  background-blend-mode:normal!important;
}
.relink-scope .rs-progress-fill{
  background:linear-gradient(135deg,var(--rs-primary),var(--rs-accent))!important;
}
.relink-scope .rs-fill-danger{
  background:linear-gradient(135deg,#c44569,#ff6b8a)!important;
}
.relink-scope .rs-fill-lust{
  background:linear-gradient(135deg,#ff5582,#ffb7c5)!important;
}
.relink-scope .rs-fill-preg{
  background:linear-gradient(135deg,#e85a7a,#c8a2c8)!important;
}

/* ========== 樱泉密事 · 移动端布局补丁 ========== */

/* 1. 聊天气泡拉宽：解决文字挤在中间的问题 */
/* 覆盖原有的 max-width 限制，让气泡占据更多空间 */
.group .max-w-md, 
.group .max-w-lg, 
.group .max-w-2xl,
.group .max-w-\[85\%\] {
    max-width: 96% !important;
}

/* 移动端针对性气泡优化 */
@media (max-width: 768px) {
    /* 强制消息容器占满屏幕宽度 */
    .group .flex.max-w-\[85\%\] {
        max-width: 98% !important;
        width: 98% !important;
    }

    /* 调整气泡内边距，增加文字展示空间 */
    .group .bg-gray-100\/90 {
        width: 100% !important;
        padding-left: 12px !important;
        padding-right: 12px !important;
    }

    /* 2. BQ/QN 系列插图放大补丁 */
    /* 将 BQ 系列图片从 50% 放大到 80%，并取消原有的 max-width 限制 */
    .story-image[class*="img-BQ-"],
    .story-image[class*="img-QN-"],
    .story-image.ratio-4x3 {
        width: 80% !important;
        max-width: 100% !important; /* 允许在气泡拉宽后随之放大 */
        margin: 1rem auto !important;
    }
}

/* 额外的视觉细节修复：确保大图在宽气泡中依然保持优雅 */
.story-image[class*="img-BQ-"] {
    border: 1px solid rgba(255, 154, 178, 0.2) !important;
    box-shadow: 0 10px 25px rgba(255, 122, 156, 0.2) !important;
}

/* ========== 樱泉密事 · 气泡可读性补丁（微透明） ========== */

/* 1. 用户气泡：保留一丝丝透明感 */
.group .bg-gray-100\/90 {
  background: linear-gradient(135deg, rgba(255,240,245,0.96), rgba(255,232,238,0.94)) !important;
}

/* 2. AI气泡：同样微透明 */
.chat-answer-container .bg-gray-100\/90 {
  background: linear-gradient(135deg, rgba(254,245,250,0.96), rgba(245,230,245,0.94)) !important;
}

/* 3. 文字颜色加深 */
.group .text-gray-900,
.group .markdown-body,
.chat-answer-container .markdown-body,
.group .text-sm,
.chat-answer-container .text-sm {
  color: #3a1f2e !important;
}

/* 4. 引用块与代码块加强 */
.group .markdown-body blockquote,
.chat-answer-container .markdown-body blockquote {
  background: rgba(255,183,197,0.18) !important;
  color: #4a2535 !important;
}

.group .markdown-body code,
.chat-answer-container .markdown-body code {
  background: rgba(255,183,197,0.30) !important;
  color: #7a1e38 !important;
}

/* ========== BQ/QN系列插图放大至80%补丁 ========== */

@media (max-width: 768px) {
    .story-image[class*="img-BQ-"],
    .story-image[class*="img-QN-"],
    .story-image.ratio-4x3 {
        width: 80% !important;
        max-width: 100% !important;
        margin: 1rem auto !important;
    }
}

.story-image[class*="img-BQ-"] {
    border: 1px solid rgba(255, 154, 178, 0.2) !important;
    box-shadow: 0 10px 25px rgba(255, 122, 156, 0.2) !important;
}

/* ==========================================
   补丁：立绘容器被省略时的灾难防御
   ========================================== */

/* 当 .rs-avatar 或 .story-image[class*="img-FZ-"] 直接出现在 .rs-panel-left 下
   （即容器被AI省略时），强制应用容器的约束规则 */
.relink-scope .rs-panel-left > .rs-avatar,
.relink-scope .rs-panel-left > .story-image[class*="img-FZ-"] {
    /* 继承容器本该有的尺寸约束 */
    width: 100% !important;
    height: auto !important;
    aspect-ratio: 2/3 !important;
    max-width: none !important;

    /* 继承容器的视觉样式 */
    margin: 0 0 14px 0 !important;
    border-radius: 12px !important;
    overflow: hidden !important;
    box-shadow: 0 12px 28px rgba(255,122,156,0.3), 0 0 24px rgba(255,183,197,0.4) !important;

    /* 确保背景图正确显示 */
    display: block !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;

    /* 防止内联样式覆盖 */
    position: relative !important;
}

/* 移动端同步修复 */
@media (max-width:768px) {
    .relink-scope .rs-panel-left > .rs-avatar,
    .relink-scope .rs-panel-left > .story-image[class*="img-FZ-"] {
        width: 78% !important;
        max-width: 280px !important;
        margin: 0 auto 12px auto !important;
    }
}

@media (max-width:480px) {
    .relink-scope .rs-panel-left > .rs-avatar,
    .relink-scope .rs-panel-left > .story-image[class*="img-FZ-"] {
        width: 88% !important;
    }
}

/* TinyFish Relink UX - Story Image Base Styles */
/* 这里的代码用于定义插图的容器基础属性，确保2:3比例及完整呈现 */

.story-image {
    /* 基础布局：宽度可根据父容器自适应，或设定固定宽度 */
    width: 100%;
    max-width: 500px; 
    margin: 1.5rem auto; 

    /* 核心比例控制：默认 2:3 比例 (宽2高3) */
    aspect-ratio: 2 / 3; 

    /* 背景图显示逻辑 */
    background-size: cover;      
    background-position: center; 
    background-repeat: no-repeat;

    /* 视觉优化：添加圆角与阴影提升梦境质感 */
    border-radius: 12px;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);

    /* 确保平滑过渡 */
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.story-image:hover {
    transform: scale(1.02);
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
}

/* ==========================================
   追加设计：4:3 比例支持与 BQ 系列专属适配
   ========================================== */

/* 1. 通用 4:3 比例修饰类 (横图) */
.story-image.ratio-4x3 {
    aspect-ratio: 4 / 3;
    max-width: 640px; /* 横图视觉占比更大，适当放宽最大宽度限制 */
    /* 备用方案：padding-bottom: 75%; */
}

/* 2. 针对 BQ-01 到 BQ-50 系列的批量自动适配 */
/* 使用 CSS 属性选择器 [class*="img-BQ-"] 自动匹配所有包含该字段的类名 */
.story-image[class*="img-BQ-"] {
    aspect-ratio: 4 / 3;
    max-width: 640px;
    /* 如果部分图需要包含完整人物而不被 cover 裁剪，可取消注释下方代码 */
    /* background-size: contain; */
    /* background-color: #1a1a1a; */ /* contain 时建议增加底色填补空白 */
}

/* ==========================================
   更新设计：4:3 比例与 BQ/QN 系列专属适配（气泡半宽 & 响应式）
   ========================================== */

/* 覆盖并合并 4:3 比例、BQ 系列与 QN 系列的样式 */
.story-image.ratio-4x3,
.story-image[class*="img-BQ-"],
.story-image[class*="img-QN-"] {
    aspect-ratio: 4 / 3;

    /* 核心修改：强制占据父容器（聊天气泡）50%的宽度 */
    width: 50%; 

    /* 响应式适配：设置上下限，防止在极端屏幕下过大或过小 */
    min-width: 140px; /* 移动端保底宽度 */
    max-width: 320px; /* PC端上限宽度 */

    /* 间距微调：保持居中 */
    margin: 0.8rem auto; 
    display: block; /* 确保 margin auto 生效 */
}

/* 移动端专属媒体查询（针对屏幕宽度小于768px的设备） */
@media screen and (max-width: 768px) {
    .story-image.ratio-4x3,
    .story-image[class*="img-BQ-"],
    .story-image[class*="img-QN-"] {
        /* 在手机端依然保持50%占比，但调整保底尺寸以适应更窄的屏幕 */
        min-width: 120px;
        /* 移动端气泡空间宝贵，进一步压缩上下间距 */
        margin: 0.5rem auto; 
        border-radius: 8px; 
    }
}

/* ==========================================
   补丁 3：粉碎输入窗口内部的白色长方形
   ========================================== */
/* 强制输入框本体透明，清除浏览器默认背景和内阴影 */
#ai-chat-input {
    background-color: transparent !important;
    background: transparent !important;
    box-shadow: none !important; /* 移除可能存在的白色内阴影 */
    -webkit-appearance: none !important;
}

/* 强制覆盖 MUI 底层组件的白色背景 (如果是 MUI 渲染的输入框) */
.MuiInputBase-root,
.MuiOutlinedInput-root {
    background-color: transparent !important;
}

/* 暴力穿透：清除输入框外层容器内包裹的任何子级白色背景块 */
.bg-white.border-\[1\.5px\] * {
    background-color: transparent !important;
}

/* 恢复发送按钮的背景，防止被上面的通配符误伤透明化 */
#ai-send-button {
    background-color: #4A313A !important;
}


/* ==========================================
   追加设计：FZ系列服装立绘专属适配 (角色名下方 2:3 80%宽度)
   ========================================== */
.relink-status-panel .story-image[class*="img-FZ-"] {
    aspect-ratio: 2 / 3 !important;
    width: 80% !important;
    max-width: 100% !important;
    /* 上下留出15px间距，左右auto实现完美居中 */
    margin: 15px auto !important;
    /* 恢复四周圆角，因为不再贴合面板边缘 */
    border-radius: 12px !important;
    /* 恢复阴影增加立体质感 */
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15) !important;
    /* 禁用悬停放大，保持面板内排版稳定 */
    transform: none !important;
}

