/* ==========================================
   新增模块 1：男主信息栏
   ========================================== */
.relink-scope .rs-player-info{
  margin-bottom:18px;padding:16px 20px;
  background:linear-gradient(135deg,rgba(240,248,255,0.95),rgba(230,240,250,0.9));
  border:1px solid rgba(100,149,237,0.3);border-radius:var(--rs-radius);
  box-shadow:0 8px 20px rgba(100,149,237,0.15);
}
.relink-scope .rs-player-header{
  font-size:15px;font-weight:700;color:#4169e1;margin-bottom:12px;
  padding-bottom:8px;border-bottom:2px solid rgba(100,149,237,0.3);
  letter-spacing:1px;
}
.relink-scope .rs-player-grid{
  display:grid;grid-template-columns:repeat(2,1fr);gap:10px;
}
.relink-scope .rs-player-item{
  padding:10px 12px;
  background:rgba(255,255,255,0.8);
  border:1px solid rgba(100,149,237,0.2);border-radius:10px;
}
.relink-scope .rs-player-item-full{
  grid-column:1 / -1;
}
.relink-scope .rs-player-label{
  font-size:12px;color:#6495ed;font-weight:600;margin-bottom:4px;
}
.relink-scope .rs-player-value{
  font-size:14px;color:var(--rs-text);font-weight:700;
}
.relink-scope .rs-player-inventory{
  font-size:13px;color:var(--rs-text);line-height:1.6;
}

/* ==========================================
   新增模块 3：世界书触发词记录栏
   ========================================== */
.relink-scope .rs-worldbook-tracker{
  margin-bottom:18px;padding:16px 20px;
