/* ==========================================
   新增模块 2：iPhone锁屏通知界面
   ========================================== */
.relink-scope .rs-iphone-mock{
  /* 尺寸优化：几乎铺满聊天窗口 */
  width:min(95%, 480px);
  max-width:480px;
  aspect-ratio:9 / 19.5;
  margin:0 auto 20px;
  position:relative;

  /* 黑色外壳 */
  background:#1a1a1a;
  border-radius:48px;
  padding:16px;

  /* 外壳阴影与高光 */
  box-shadow:
    0 28px 80px rgba(0,0,0,0.6),
    inset 0 0 0 2px rgba(255,255,255,0.08),
    inset 0 1px 0 rgba(255,255,255,0.15);
}

/* 刘海（灵动岛样式） */
.relink-scope .rs-iphone-notch{
  position:absolute;
  top:0;left:50%;transform:translateX(-50%);
  width:180px;height:36px;
  background:#000;
  border-radius:0 0 22px 22px;
  z-index:10;
  box-shadow:0 2px 8px rgba(0,0,0,0.3);
}

/* 屏幕容器 */
.relink-scope .rs-iphone-screen{
  width:100%;
  height:100%;

  /* 背景图：自适应覆盖 */
  background:
    linear-gradient(180deg, rgba(10,10,15,0.4), rgba(10,10,15,0.6)),
    url('https://miha.wiki/41lTeM.png');
  background-size:cover;
  background-position:center;

  border-radius:36px;
  overflow:hidden;
  padding:52px 20px 32px;

  display:flex;
  flex-direction:column;
  position:relative;
}

/* 锁屏顶部时间显示 */
.relink-scope .rs-lockscreen-time{
  text-align:center;
  color:#fff;
  margin-bottom:8px;
}

.relink-scope .rs-lockscreen-hour{
  font-size:72px;
  font-weight:300;
  line-height:1;
  letter-spacing:-2px;
  text-shadow:0 3px 12px rgba(0,0,0,0.6);
}

.relink-scope .rs-lockscreen-date{
  font-size:16px;
  font-weight:500;
  color:rgba(255,255,255,0.85);
  margin-top:4px;
  text-shadow:0 2px 6px rgba(0,0,0,0.5);
}

/* 通知卡片容器 */
.relink-scope .rs-notifications{
  flex:1;
  padding-top:28px;
  display:flex;
  flex-direction:column;
  gap:12px;
  overflow-y:auto;
  overflow-x:hidden;
}

.relink-scope .rs-notifications::-webkit-scrollbar{
  width:4px;
}

.relink-scope .rs-notifications::-webkit-scrollbar-track{
  background:transparent;
}

.relink-scope .rs-notifications::-webkit-scrollbar-thumb{
