   放在整份 CSS 最末尾
   ========================================== */

/* 手机屏幕本体：允许滑动，但不显示滚动条、不预留滚动条槽位 */
.relink-scope .rs-iphone-screen {
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  -webkit-overflow-scrolling: touch !important;
  scrollbar-gutter: auto !important;
}

/* Chrome / Edge / Safari 隐藏屏幕滚动条 */
.relink-scope .rs-iphone-screen::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
  background: transparent !important;
}

/* 真正滚动的是通知列表：这里必须一起隐藏 */
.relink-scope .rs-notifications {
  flex: 1 !important;
  padding-top: 18px !important;
  padding-bottom: 74px !important;

  display: flex !important;
  flex-direction: column !important;
  gap: 12px !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  -webkit-overflow-scrolling: touch !important;

  /*
    核心：上下渐隐。
    18px 开始完全显示，底部 52px 前开始渐隐，
    这样通知卡片会更靠近屏幕边缘才消失。
  */
  mask-image: linear-gradient(
    to bottom,
    transparent 0px,
    rgba(0, 0, 0, 0.25) 8px,
    #000 18px,
    #000 calc(100% - 52px),
    rgba(0, 0, 0, 0.25) calc(100% - 24px),
    transparent 100%
  ) !important;

  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0px,
    rgba(0, 0, 0, 0.25) 8px,
    #000 18px,
    #000 calc(100% - 52px),
    rgba(0, 0, 0, 0.25) calc(100% - 24px),
    transparent 100%
  ) !important;
}

/* 强制干掉你前面写过的 4px 滚动条 */
.relink-scope .rs-notifications::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
  background: transparent !important;
}

.relink-scope .rs-notifications::-webkit-scrollbar-track {
  display: none !important;
  background: transparent !important;
}

.relink-scope .rs-notifications::-webkit-scrollbar-thumb {
  display: none !important;
  background: transparent !important;
}

/* 通知卡片靠近边缘时更自然：不再被硬切 */
.relink-scope .rs-notification-card {
  flex-shrink: 0 !important;
  will-change: transform, opacity !important;
}

/* 底部提示稍微贴底，让通知能滑到更外侧 */
.relink-scope .rs-lockscreen-hint {
  padding: 10px 0 4px !important;
  margin-top: 0 !important;
}

/* 小屏幕：渐隐范围稍微缩小，避免内容被吃太多 */
@media (max-width: 480px) {
  .relink-scope .rs-notifications {
    padding-top: 14px !important;
    padding-bottom: 64px !important;

    mask-image: linear-gradient(
      to bottom,
      transparent 0px,
      rgba(0, 0, 0, 0.3) 6px,
      #000 14px,
      #000 calc(100% - 44px),
      rgba(0, 0, 0, 0.3) calc(100% - 20px),
      transparent 100%
    ) !important;

    -webkit-mask-image: linear-gradient(
      to bottom,
      transparent 0px,
      rgba(0, 0, 0, 0.3) 6px,
      #000 14px,
      #000 calc(100% - 44px),
      rgba(0, 0, 0, 0.3) calc(100% - 20px),
      transparent 100%
    ) !important;
  }
}

/* ==========================================
   最终补丁：移动端 iPhone 拉满宽度 + 通知内容扩展
   放在整份 CSS 最末尾
   ========================================== */

/* 默认：让手机更接近聊天气泡宽度 */
.relink-scope .rs-iphone-mock {
  width: min(100%, 560px) !important;
