  .rs-notif-body .rs-wechat-video {
    width: 60% !important;
    max-width: 150px !important;
    margin-top: 8px !important;
  }

  .rs-notif-body .rs-wechat-video::after {
    width: 40px !important;
    height: 40px !important;
