/* ========== 最终修复：移动端电池归位 ========== */
.relink-scope .rs-iphone-mock,
.relink-scope .rs-iphone-screen {
  position: relative !important;
}

.relink-scope .rs-iphone-screen::before {
  top: clamp(14px, 2.8vw, 18px) !important;
  right: clamp(72px, 15vw, 92px) !important;
}

.relink-scope .rs-iphone-screen::after {
  top: clamp(14px, 2.8vw, 18px) !important;
  right: clamp(16px, 3.5vw, 24px) !important;
}

.relink-scope .rs-iphone-mock::before {
  top: clamp(27px, 5.4vw, 35px) !important;
  right: clamp(60px, 12.5vw, 78px) !important;
}

.relink-scope .rs-iphone-mock::after {
  top: clamp(29px, 5.8vw, 37px) !important;
  right: clamp(57px, 12vw, 75px) !important;
}

@media (max-width: 480px) {
  .relink-scope .rs-iphone-screen::before {
    top: 13px !important;
    right: 66px !important;
  }

  .relink-scope .rs-iphone-screen::after {
    top: 13px !important;
    right: 14px !important;
  }

  .relink-scope .rs-iphone-mock::before {
    top: 26px !important;
    right: 52px !important;
  }

  .relink-scope .rs-iphone-mock::after {
    top: 28px !important;
    right: 49px !important;
  }
}

/* ========== 仅移动端修复：电池微调，PC端不改 ========== */
@media (max-width: 768px) {
  .rs-iphone-screen,
  .relink-scope .rs-iphone-screen,
  .rs-iphone-mock,
  .relink-scope .rs-iphone-mock {
    position: relative !important;
  }

  /* 信号：保持移动端原位置 */
  .rs-iphone-screen::before,
  .relink-scope .rs-iphone-screen::before {
    top: 13px !important;
    right: 68px !important;
  }

  /* 80%文字：保持移动端原位置 */
  .rs-iphone-screen::after,
  .relink-scope .rs-iphone-screen::after {
    top: 13px !important;
    right: 14px !important;
  }

  /* 电池主体：只在移动端往左一点 */
  .rs-iphone-mock::before,
  .relink-scope .rs-iphone-mock::before {
    top: 22px !important;
    right: 50px !important;
  }

  /* 电池凸起：跟着主体左移 */
  .rs-iphone-mock::after,
  .relink-scope .rs-iphone-mock::after {
    top: 24px !important;
    right: 47px !important;
  }
}

@media (max-width: 480px) {
  /* 小屏手机再单独微调 */
  .rs-iphone-screen::before,
  .relink-scope .rs-iphone-screen::before {
    top: 12px !important;
    right: 64px !important;
  }

  .rs-iphone-screen::after,
  .relink-scope .rs-iphone-screen::after {
    top: 12px !important;
    right: 13px !important;
  }

  .rs-iphone-mock::before,
  .relink-scope .rs-iphone-mock::before {
    top: 20px !important;
    right: 45px !important;
  }

  .rs-iphone-mock::after,
  .relink-scope .rs-iphone-mock::after {
    top: 22px !important;
    right: 42px !important;
  }
}

/* ========== 移动端微调：80% 电量文字右移一点 ========== */
