/* =========================================================
   Relink A→B 兼容补丁：短类名模板完整继承原美化
   放在整份 CSS 最末尾
   ========================================================= */

/* ---------- 0. B模板根变量 ---------- */
.rls,
.rls *,
.pif,
.pif *,
.wbt,
.wbt *,
.ipm,
.ipm *,
.chb,
.chb * {
  --rs-primary:#ff7a9c;
  --rs-accent:#c8a2c8;
  --rs-sakura:#ffb7c5;
  --rs-text:#4a2c3d;
  --rs-text-sub:#8a6478;
  --rs-text-light:#a88497;
  --rs-bg-card:rgba(255,250,252,0.96);
  --rs-bg-soft:rgba(255,240,245,0.85);
  --rs-bg-inner:rgba(255,255,255,0.7);
  --rs-border:rgba(255,154,178,0.32);
  --rs-border-soft:rgba(200,162,200,0.22);
  --rs-shadow:0 10px 36px rgba(255,122,156,0.18),0 0 24px rgba(255,183,197,0.15);
  --rs-glow:0 0 16px rgba(255,183,197,0.45);
  --rs-radius:18px;
  --rs-radius-sm:10px;
  --rs-lv1:#a8d8b9;
  --rs-lv2:#ffd97d;
  --rs-lv3:#ffa07a;
  --rs-lv4:#ff6b8a;
  --rs-lv5:#c44569;
  box-sizing:border-box!important;
  font-family:"Noto Serif JP","PingFang SC","Microsoft YaHei",system-ui,-apple-system,sans-serif!important;
}

/* ---------- 1. B模板外壳继承 relink-scope ---------- */
.rls {
  color:var(--rs-text)!important;
  max-width:880px!important;
  margin:18px auto!important;
  padding:22px!important;
  background:
    linear-gradient(135deg,rgba(255,245,247,0.92),rgba(245,232,245,0.88)),
    radial-gradient(ellipse at top right,rgba(255,183,197,0.18),transparent 60%)!important;
  backdrop-filter:blur(14px)!important;
  -webkit-backdrop-filter:blur(14px)!important;
  border:1px solid var(--rs-border)!important;
  border-radius:24px!important;
  box-shadow:var(--rs-shadow)!important;
  position:relative!important;
  overflow:hidden!important;
  animation:rs-fade-in 0.8s ease both!important;
}

.rls::before {
  content:""!important;
  position:absolute!important;
  top:0!important;
  left:0!important;
  right:0!important;
  height:3px!important;
  background:linear-gradient(90deg,var(--rs-primary),var(--rs-sakura),var(--rs-accent),var(--rs-primary))!important;
  background-size:200% 100%!important;
  animation:rs-flow 4s linear infinite!important;
}

/* ---------- 2. 场景头部 ---------- */
.rls .tgs {
  display:grid!important;
  grid-template-columns:repeat(4,1fr)!important;
  gap:10px!important;
  margin-bottom:10px!important;
}

.rls .tag {
  display:flex!important;
  align-items:center!important;
  gap:6px!important;
  padding:8px 12px!important;
  background:linear-gradient(135deg,rgba(255,255,255,0.85),rgba(255,232,238,0.7))!important;
  border:1px solid var(--rs-border)!important;
  border-radius:12px!important;
  font-size:13px!important;
  color:var(--rs-text)!important;
  box-shadow:0 2px 6px rgba(255,122,156,0.08)!important;
  transition:transform 0.25s ease,box-shadow 0.25s ease!important;
}

.rls .tag:hover {
  transform:translateY(-2px)!important;
  box-shadow:0 4px 12px rgba(255,122,156,0.2)!important;
}

.rls .tag b {
  color:var(--rs-primary)!important;
  font-weight:700!important;
}

.rls .ico {
  font-size:14px!important;
  filter:drop-shadow(0 0 4px rgba(255,183,197,0.6))!important;
}

.rls .scd {
  padding:10px 14px!important;
  background:rgba(255,183,197,0.12)!important;
  border-left:3px solid var(--rs-primary)!important;
  border-radius:0 10px 10px 0!important;
  font-size:14px!important;
  color:var(--rs-text)!important;
}

.rls .scd b {
  color:var(--rs-primary)!important;
  font-weight:700!important;
}

/* ---------- 3. 状态面板 ---------- */
.rls .stp {
  display:grid!important;
  grid-template-columns:260px 1fr!important;
  grid-template-areas:"left right" "bottom bottom"!important;
  gap:18px!important;
  margin-bottom:18px!important;
}

.rls .pnl {
  grid-area:left!important;
  padding:16px!important;
  display:flex!important;
  flex-direction:column!important;
  align-items:stretch!important;
  background:linear-gradient(160deg,rgba(255,250,252,0.95),rgba(255,232,238,0.85))!important;
  border:1px solid var(--rs-border)!important;
  border-radius:var(--rs-radius)!important;
  box-shadow:var(--rs-shadow)!important;
  text-align:center!important;
}

.rls .pnr {
  grid-area:right!important;
  padding:18px!important;
  background:var(--rs-bg-card)!important;
  border:1px solid var(--rs-border)!important;
  border-radius:var(--rs-radius)!important;
  box-shadow:var(--rs-shadow)!important;
}

/* ---------- 4. 立绘 ---------- */
.rls .avb {
  position:relative!important;
  width:100%!important;
  height:auto!important;
  aspect-ratio:2/3!important;
  max-width:none!important;
  margin:0 0 14px 0!important;
  border-radius:12px!important;
  overflow:hidden!important;
  display:block!important;
  font-size:0!important;
  line-height:0!important;
  box-shadow:0 12px 28px rgba(255,122,156,0.3),0 0 24px rgba(255,183,197,0.4)!important;
  animation:rs-glow-pulse 3.5s ease infinite!important;
}

.rls .avb::after {
  content:""!important;
  position:absolute!important;
  inset:0!important;
  background:linear-gradient(180deg,transparent 65%,rgba(74,44,61,0.35))!important;
  pointer-events:none!important;
}

.rls .avb .ava,
