/* ==========================================
   补丁：AI加载动画 → 小女孩吃蛋糕三连图（每0.5s切换+左右摆动）
   放在整份 CSS 最末尾，会覆盖原有的 SVG SMIL 加载动画
   ========================================== */

/* 1. 强制隐藏平台默认的小圆点闪烁动画 */
.style_dot-flashing__8L91Q {
  display: none !important;
}

/* 2. 加载容器：扩大尺寸放下完整人物，定位基准 */
.flex.items-center.justify-center.w-6.h-5 {
  position: relative !important;
  width: 88px !important;
  height: 88px !important;
  /* 给左右摆动预留呼吸空间，避免被父容器裁切 */
  overflow: visible !important;
}

/* 3. 用 ::before 承载图片切换 + 摆动动画 */
.flex.items-center.justify-center.w-6.h-5::before {
  content: '' !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;

  /* 默认先放第一张，防止动画未触发时空白 */
  background-image: url('https://i.ibb.co/5WvPxbjp/grok-image-424d845d-8d7d-4f74-987d-d034a8ee4ef8-removebg-preview.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center bottom !important;

  /* 以底部为旋转支点：更像小女孩坐着左右晃身体 */
  transform-origin: center bottom !important;

  /* 主题柔光 + 轻微投影，融入樱泉密事粉调 */
  filter:
    drop-shadow(0 4px 10px rgba(255, 122, 156, 0.35))
    drop-shadow(0 0 6px rgba(255, 183, 197, 0.45)) !important;

  /* 关键：steps(1) 让图片"啪"地切换，不会出现奇怪的渐变叠图 */
  animation: cake-girl-loader 1.5s steps(1, end) infinite !important;
}

/* 4. 三帧动画：每张图 0.5s，配合左右摆动节奏 */
@keyframes cake-girl-loader {
  /* 第 1 帧（0 ~ 0.5s）：图1 + 左倾 */
  0% {
